// Month-over-month comparison per competitor: last 30 days vs the 30 days before
const wanted = String($('When Called by Agent').first().json.competitor || 'all').trim().toLowerCase();
const now = Date.now(), DAY = 86400000;
const cur = {}, prev = {};
function add(map, r) {
  const k = r.competitor;
  map[k] ??= { items: 0, high_impact: 0, score_sum: 0, categories: {} };
  const m = map[k], s = Number(r.impact_score) || 0;
  m.items++; m.score_sum += s; if (s >= 7) m.high_impact++;
  m.categories[r.category] = (m.categories[r.category] || 0) + 1;
}
for (const { json: r } of $input.all()) {
  if (!r.competitor) continue;
  if (wanted && wanted !== 'all' && String(r.competitor).toLowerCase() !== wanted) continue;
  const t = Date.parse(r.date || r.published);
  if (isNaN(t)) continue;
  const age = now - t;
  if (age <= 30 * DAY) add(cur, r); else if (age <= 60 * DAY) add(prev, r);
}
const fmt = m => m
  ? { items: m.items, high_impact: m.high_impact, avg_impact: +(m.score_sum / m.items).toFixed(1), categories: m.categories }
  : { items: 0, high_impact: 0, avg_impact: 0, categories: {} };
const names = [...new Set([...Object.keys(cur), ...Object.keys(prev)])];
const comparison = names.map(n => {
  const a = fmt(cur[n]), b = fmt(prev[n]);
  return { competitor: n, last_30_days: a, previous_30_days: b,
           change_in_items: a.items - b.items, change_in_avg_impact: +(a.avg_impact - b.avg_impact).toFixed(1) };
});
return [{ json: { generated_at: new Date().toISOString(), competitor_filter: wanted, comparison,
  note: comparison.length ? '' : 'No logged items in the last 60 days.' } }];
